//! Runs `tests/data/wand_fixtures.json`: the casting fixtures of the research data that only use
//! the 25 in-scope spells, with the wrong expectations corrected (generated by
//! `python -m noitabench.content_tools.build_wand_fixtures`).
//!
//! The runner fails on a fixture key it does not know, so a new fixture can never pass by having
//! its expectations silently ignored.

mod common;

use cogbench_game::spell::TriggerKind;
use cogbench_game::wand::{CastResult, Wand, WandStats};
use cogbench_game::{SpellBook, SpellId};
use common::*;
use serde_json::Value;

const FIXTURES: &str = include_str!("data/wand_fixtures.json");

/// Keys of a fixture / click / variant that carry no expectation.
const NOTES: [&str; 5] = ["id", "source", "verified", "note", "corrected"];

fn str_list(value: &Value) -> Vec<String> {
    value
        .as_array()
        .expect("a list")
        .iter()
        .map(|v| v.as_str().expect("a string").to_string())
        .collect()
}

fn stats_of(defaults: &Value, wand: Option<&Value>) -> (WandStats, Vec<String>) {
    let mut merged = defaults.clone();
    let mut always = Vec::new();
    if let Some(over) = wand {
        for (key, value) in over.as_object().expect("an object") {
            if key == "always_casts" {
                always = str_list(value);
            } else {
                merged[key] = value.clone();
            }
        }
    }
    let num = |k: &str| merged[k].as_f64().unwrap_or_else(|| panic!("wand.{k}"));
    let stats = WandStats {
        shuffle: merged["shuffle"].as_bool().expect("shuffle"),
        spells_per_cast: num("spells_per_cast") as u32,
        cast_delay: num("cast_delay_frames") as i32,
        recharge: num("recharge_frames") as i32,
        mana_max: num("mana_max") as f32,
        mana_charge_speed: num("mana_charge_speed") as f32,
        capacity: num("capacity") as u32,
        spread: num("spread") as f32,
        speed_multiplier: num("speed_multiplier") as f32,
    };
    (stats, always)
}

/// Indices that make the "remove a random card" shuffle produce `permutation` from `slots`.
fn shuffle_script(slots: &[String], permutation: &[String]) -> Scripted {
    let mut remaining: Vec<&String> = slots.iter().collect();
    let mut indices = Vec::new();
    for wanted in permutation {
        let at = remaining
            .iter()
            .position(|k| *k == wanted)
            .expect("permutation of the slots");
        indices.push(at as u32);
        remaining.remove(at);
    }
    Scripted::with_indices(&indices)
}

fn build_wand(book: &SpellBook, case: &Value, defaults: &Value) -> Wand {
    let (stats, always) = stats_of(defaults, case.get("wand"));
    let slots: Vec<Option<SpellId>> = str_list(&case["slots"])
        .iter()
        .map(|k| Some(id(book, k)))
        .collect();
    let always: Vec<SpellId> = always.iter().map(|k| id(book, k)).collect();
    Wand::new(book, stats, &slots, &always).expect("valid wand")
}

fn check_f32(label: &str, got: f32, expected: &Value) {
    let want = expected
        .as_f64()
        .unwrap_or_else(|| panic!("{label}: a number")) as f32;
    assert!(approx(got, want), "{label}: got {got}, expected {want}");
}

fn check_payloads(book: &SpellBook, label: &str, result: &CastResult, payloads: &Value) {
    for expected in payloads.as_array().expect("payloads") {
        let carrier = expected["of"].as_str().expect("of");
        let spawn = result
            .projectiles
            .iter()
            .find(|p| book.key(p.spell) == carrier && p.trigger.is_some())
            .unwrap_or_else(|| panic!("{label}: no trigger projectile {carrier}"));
        let trigger = spawn.trigger.as_ref().expect("trigger");
        for (key, value) in expected.as_object().expect("payload") {
            match key.as_str() {
                "of" | "note" => {}
                "kind" => {
                    let kind = value.as_str().expect("kind");
                    assert_eq!(trigger.kind, TriggerKind::Collision, "{label}: kind {kind}");
                    assert_eq!(kind, "hit_world");
                }
                "projectiles" => {
                    assert_eq!(
                        spawn_keys(book, &trigger.payload),
                        str_list(value),
                        "{label}: payload"
                    );
                }
                "modifiers" => {
                    let got = keys_of(book, &trigger.payload[0].shot.modifiers);
                    assert_eq!(got, str_list(value), "{label}: payload modifiers");
                }
                "damage_projectile_add_internal" => {
                    check_f32(
                        &format!("{label}: payload damage"),
                        trigger.payload[0].shot.damage,
                        value,
                    );
                }
                other => panic!("{label}: unknown payload key {other}"),
            }
        }
    }
}

fn check_click(book: &SpellBook, label: &str, result: &CastResult, expected: &Value) {
    for (key, value) in expected.as_object().expect("click") {
        let got_label = format!("{label}: {key}");
        match key.as_str() {
            k if NOTES.contains(&k) => {}
            "projectiles" => assert_eq!(
                spawn_keys(book, &result.projectiles),
                str_list(value),
                "{got_label}"
            ),
            "modifiers" => assert_eq!(
                keys_of(book, &result.root.modifiers),
                str_list(value),
                "{got_label}"
            ),
            "damage_projectile_add_internal" | "root_damage_projectile_add_internal" => {
                check_f32(&got_label, result.root.damage, value)
            }
            "crit_chance" | "root_crit_chance" => {
                check_f32(&got_label, result.root.crit_chance, value)
            }
            "root_speed_multiplier" => check_f32(&got_label, result.root.speed_mul, value),
            "fire_rate_wait_frames" | "root_fire_rate_wait_frames" => {
                check_f32(&got_label, result.root.cast_delay as f32, value)
            }
            "mana_spent" => check_f32(&got_label, result.mana_spent, value),
            "mana_after" => check_f32(&got_label, result.mana_after, value),
            "recharge_after" => assert_eq!(
                result.recharge.is_some(),
                value.as_bool().unwrap(),
                "{got_label}"
            ),
            "wrapped" => assert_eq!(result.wrapped, value.as_bool().unwrap(), "{got_label}"),
            "payloads" => check_payloads(book, label, result, value),
            other => panic!("{label}: the runner does not know the fixture key {other:?}"),
        }
    }
}

fn run_case(book: &SpellBook, case: &Value, defaults: &Value) {
    let case_id = case["id"].as_str().expect("id");
    let slots = str_list(&case["slots"]);
    let mut rng = match case.get("forced_permutation") {
        Some(p) => shuffle_script(&slots, &str_list(p)),
        None => Scripted::new(),
    };
    for key in case.as_object().expect("case").keys() {
        let known = ["clicks", "slots", "wand", "forced_permutation", "variants"];
        assert!(
            NOTES.contains(&key.as_str()) || known.contains(&key.as_str()),
            "{case_id}: key {key}"
        );
    }
    // The clicks of one case follow each other on the same wand.
    if let Some(clicks) = case.get("clicks").and_then(Value::as_array) {
        let mut wand = build_wand(book, case, defaults);
        for (i, click) in clicks.iter().enumerate() {
            let result = cast_and_wait(&mut wand, book, &mut rng);
            check_click(book, &format!("{case_id} click {i}"), &result, click);
        }
    }
    for (i, variant) in case
        .get("variants")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .enumerate()
    {
        let mut wand = build_wand(book, case, defaults);
        wand.set_mana(variant["mana"].as_f64().expect("variant mana") as f32);
        let result = wand.cast(book, &mut rng).expect("ready");
        check_click(
            book,
            &format!("{case_id} variant {i}"),
            &result,
            &variant["expect"],
        );
    }
}

#[test]
fn the_fixture_file_has_the_in_scope_cases() {
    let doc: Value = serde_json::from_str(FIXTURES).unwrap();
    assert_eq!(doc["format"], "cogbench-wand-fixtures/0");
    assert_eq!(doc["cases"].as_array().unwrap().len(), 9);
    assert!(doc["excluded"].as_object().unwrap().len() >= 20);
}

#[test]
fn wand_fixtures_pass() {
    let book = book();
    let doc: Value = serde_json::from_str(FIXTURES).unwrap();
    let defaults = &doc["default_wand"];
    for case in doc["cases"].as_array().unwrap() {
        run_case(&book, case, defaults);
    }
}

#[test]
fn draw_01_has_the_corrected_mana_expectation() {
    // DN-WAND-09: BURST_2 is free, so DAMAGE 5 + 2 x LIGHT_BULLET 5 = 15 (the research file said 10).
    let doc: Value = serde_json::from_str(FIXTURES).unwrap();
    let case = doc["cases"]
        .as_array()
        .unwrap()
        .iter()
        .find(|c| c["id"] == "draw_01_multicast_modifier")
        .unwrap();
    assert_eq!(case["clicks"][0]["mana_spent"], 15);
    assert!(case["corrected"][0]
        .as_str()
        .unwrap()
        .contains("DN-WAND-09"));
}
